import {
  LONGITUDINAL_ASSAY_PROFILE_ID,
  LONGITUDINAL_ASSAY_SCHEMA_VERSION,
  LONGITUDINAL_GBM_PROFILE_ID,
  LONGITUDINAL_SOURCE_PROFILE_DIGEST,
} from "../../src/lib/longitudinal-gbm";

const digest = `sha256:${"a".repeat(64)}`;
const requestDigest = `sha256:${"b".repeat(64)}`;
const resultDigest = `sha256:${"c".repeat(64)}`;
const normalizationDigest = `sha256:${"d".repeat(64)}`;

const genes = ["EGFR", "PTEN", "NF1", "PDGFRA"] as const;
const pointIds = ["synthetic.baseline", "synthetic.followup.a", "synthetic.followup.b", "synthetic.followup.c"] as const;
const offsets = [0, 90, 210, 365] as const;
const abundance = [
  [12.0, 11.7, 10.2, 9.8],
  [12.8, 11.1, 11.0, 10.9],
  [12.1, 11.6, 10.6, 10.3],
  [12.12, 11.58, 10.62, 10.29],
] as const;

export const longitudinalDemoRequest = {
  profile_id: LONGITUDINAL_GBM_PROFILE_ID,
  series_id: "synthetic-kncc-longitudinal-protein-series-v1",
  assay_compatibility: {
    schema_version: LONGITUDINAL_ASSAY_SCHEMA_VERSION,
    compatibility_profile_id: LONGITUDINAL_ASSAY_PROFILE_ID,
    source_profile_content_digest: LONGITUDINAL_SOURCE_PROFILE_DIGEST,
    assay: "tmt11_plexed_mass_spectrometry",
    quantification: "unshared_peptide_protein_abundance_ratio",
    value_transformation: "log2_ratio",
    log_base: 2,
    invariant_across_time_points: true,
    attested_compatible: true,
  },
  normalization_reference: {
    reference_id: "synthetic.kncc.log2.reference.v1",
    binding_digest: normalizationDigest,
    normalization_method: "synthetic invariant log2 protein-abundance reference",
    abundance_scale: "caller_supplied_log2_protein_abundance_ratio",
    invariant_across_time_points: true,
  },
  time_points: pointIds.map((timePointId, pointIndex) => ({
    time_point_id: timePointId,
    time_offset_days: offsets[pointIndex],
    normalization_reference_digest: normalizationDigest,
    observations: genes.map((geneSymbol, geneIndex) => ({
      observation_id: `demo.${pointIndex}.${geneIndex}`,
      gene_symbol: geneSymbol,
      state: pointIndex === 2 && geneIndex === 3 ? "left_censored" : "observed",
      log_abundance: abundance[pointIndex][geneIndex],
      standard_error: 0.04 + geneIndex * 0.01,
      quality_weight: 0.95,
      provenance_digest: digest,
    })),
  })),
  bootstrap_replicates: 32,
};

function transition(index: number, score: number, classification: string) {
  const gene = genes[index];
  return {
    transition_id: `transition.${index}`,
    transition_index: index,
    from_time_point_id: pointIds[index],
    to_time_point_id: pointIds[index + 1],
    support: "limited",
    classification,
    score,
    lower_bound: score - 0.12,
    upper_bound: score + 0.12,
    interval_level: 0.9,
    bootstrap_replicates_used: 32,
    shared_active_gene_count: 4,
    effective_sample_size: 3.7,
    coverage: 0.84 + index * 0.03,
    source_support_percentile: 0.72 + index * 0.08,
    measurement_uncertainty: { state: "estimated", standard_error: 0.06, variance_fraction: 0.42, bootstrap_replicates_used: 32, reason: null },
    coefficient_uncertainty: { state: "estimated", standard_error: 0.08, variance_fraction: 0.58, bootstrap_replicates_used: 32, reason: null },
    uncertainty_interaction: {
      state: "estimated",
      method: "paired_bootstrap_covariance_identity_v1",
      covariance: -0.0005,
      variance_contribution: -0.001,
      combined_variance: 0.009,
      decomposition_residual: 0,
      bootstrap_replicates_used: 32,
      reason: null,
    },
    top_drivers: [{
      gene_symbol: gene,
      source_gene_label: gene,
      from_observation_id: `demo.${index}.${index}`,
      to_observation_id: `demo.${index + 1}.${index}`,
      from_provenance_digest: digest,
      to_provenance_digest: digest,
      from_state: "observed",
      to_state: "observed",
      value_semantics: "exact_delta",
      standardized_delta: score > 0 ? 1.1 : -0.9,
      model_coefficient: 0.72,
      signed_contribution: score * 0.62,
      direction: score >= 0 ? "source_recurrence_aligned" : "reverse_aligned",
      reliability_weight: 0.94,
      source_feature_support: 101,
    }],
    source_processing_ablations: [{
      comparison: "ordinary Log identification-ambiguity/shared-peptide ablation; caller observations unchanged",
      support: "limited",
      score_without_component: score * 0.86,
      score_delta: score * 0.14,
      classification_without_component: classification,
      reason: "Transition support is limited by fewer than 64 estimable bootstrap projections; sensitivity analysis only, not independent validation.",
    }],
    top_driver_ablations: [{
      omitted_gene_symbol: gene,
      omitted_signed_contribution: score * 0.62,
      support: "limited",
      score_without_component: score * 0.38,
      score_delta: score * 0.62,
      classification_without_component: index === 2 ? "stable" : classification,
      reason: "Transition support is limited by fewer than 64 estimable bootstrap projections.",
    }],
    abstention_reasons: ["fewer than 64 estimable bootstrap projections for fully supported uncertainty"],
  };
}

